__NUXT_JSONP__("/desarrollo-sostenible/columnas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{columnas:[{slug:"rezagos_en_infraestructura_hidrica_y_recorte_al_presupuesto_de_conagua_en_2026",title:"Rezagos en infraestructura hídrica y recorte al presupuesto de Conagua en 2026",date:"2025-10-03T18:15:11.898Z",img:"https:\u002F\u002Fucarecdn.com\u002F57c6916a-5295-4371-9c56-714538cd984c\u002F","img-alt":"Conagua",autor:"Agustín Castillo",medio:f,link:"https:\u002F\u002Fpolitica.expansion.mx\u002Fvoces\u002F2025\u002F10\u002F03\u002Frezagos-en-infraestructura-hidrica-y-recorte-al-presupuesto-de-conagua-en-2026",category:a,extracto:"El déficit presupuestario en materia hídrica no permite avanzar en garantizar el Derecho Humano al agua. Es necesario hacer asignaciones presupuestales suficientes considerando los retos en el sector.",toc:[],dir:b,path:"\u002Fcolumnas\u002Frezagos_en_infraestructura_hidrica_y_recorte_al_presupuesto_de_conagua_en_2026",extension:c,createdAt:"2025-11-25T01:24:03.247Z",updatedAt:"2025-11-25T01:24:03.248Z"},{slug:"como_enfrentar_la_resistencia_a_la_transicion_energetica_lecciones_de_la_abolicion_de_la_esclavitud",title:"¿Cómo enfrentar la resistencia a la transición energética? Lecciones de la abolición de la esclavitud",date:"2024-10-17T17:47:31.452Z",img:"https:\u002F\u002Fucarecdn.com\u002F76b1d685-bfef-4828-b251-a839d267ac96\u002F-\u002Fcrop\u002F740x380\u002F0,342\u002F-\u002Fpreview\u002F","img-alt":"Transición energética",autor:"Laure Delalande y Humberto Gutiérrez",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fresistencia-transicion-energetica",category:a,extracto:"La abolición de la esclavitud y la crisis climática comparten una problemática similar: la necesidad de forzar una transición de un modelo de producción económica basado en un “insumo” de naturaleza crítica, pero insostenible, hacia un esquema de producción económica que no dependa más de dicho insumo.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fcomo_enfrentar_la_resistencia_a_la_transicion_energetica_lecciones_de_la_abolicion_de_la_esclavitud",extension:c,createdAt:g,updatedAt:g},{slug:"un_respiro_a_la_tierra",title:"¿Un respiro a la tierra?",date:"2024-06-05T15:56:29.338Z",img:"https:\u002F\u002Fucarecdn.com\u002F37a38cbe-f052-4790-b28f-7b1fd461a82b\u002F","img-alt":"Día Mundial del Medio Ambiente",autor:e,medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fun-respiro-a-la-tierra",category:a,extracto:"La crisis ambiental se ha vuelto tan común que corre el riesgo de ser aceptada como parte de la normalidad y, por tanto, de una ideología que sea difícil de reflexionar.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fun_respiro_a_la_tierra",extension:c,createdAt:h,updatedAt:h},{slug:"no_no_es_normal_este_calor",title:"No, no es normal este calor",date:"2024-05-25T15:56:20.707Z",img:"https:\u002F\u002Fucarecdn.com\u002F4e3eb55a-b443-4c61-86cf-3d4e45fe1069\u002F","img-alt":"Domo de calor en México",autor:e,medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fno-es-normal-este-calor",category:a,extracto:"No son normales las temperaturas que sentimos, ni tampoco es normal la desigualdad en las emisiones de carbono, pues subraya una injusticia fundamental en la distribución de la responsabilidad y el impacto del cambio climático.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fno_no_es_normal_este_calor",extension:c,createdAt:i,updatedAt:i},{slug:"que_futuro_socioambiental_nos_ofrecen_las_candidatas_a_la_presidencia",title:"¿Qué futuro socioambiental nos ofrecen las candidatas a la presidencia?",date:"2024-05-06T22:41:32.477Z",img:"https:\u002F\u002Fucarecdn.com\u002F146c04ab-a888-4241-bc6a-61177aa35ea1\u002F","img-alt":"Futuro medioambiental",autor:"Néstor Genis y Fernanda Flores",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ffuturo-socioambiental-oferta-candidatas",category:a,extracto:"En los discursos de las candidatas a la presidencia se pueden identificar algunas prioridades compartidas, aunque con diferentes enfoques y sin dejar muy claros los “cómos”: transición energética, atención de la crisis hídrica y promoción de la electromovilidad y energía solar de uso doméstico. Sin embargo, para todas estas propuestas queda la duda, ¿cómo se va a financiar?",toc:[],dir:b,path:"\u002Fcolumnas\u002Fque_futuro_socioambiental_nos_ofrecen_las_candidatas_a_la_presidencia",extension:c,createdAt:j,updatedAt:j},{slug:"es_hora_de_crear_nuestros_propios_huertos",title:"¿Es hora de crear nuestros propios huertos?",date:"2024-02-27T23:07:06.300Z",img:"https:\u002F\u002Fucarecdn.com\u002F66008e73-a747-48d4-a4da-0aa44792094e\u002F","img-alt":"Huertos urbanos",autor:e,medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fhuertos-urbanos-sistema-alimentario",category:a,extracto:"Estamos en un punto de inflexión donde sembrar nuestros propios alimentos se convierte en un acto de resistencia y autonomía, desafiando las contradicciones del sistema alimentario actual y construyendo un futuro más resiliente.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fes_hora_de_crear_nuestros_propios_huertos",extension:c,createdAt:k,updatedAt:k},{slug:"escasez_de_agua_o_desastres_naturales_por_donde_llegara_la_primera_gran_crisis_del_cambio_climatico",title:"Escasez de agua o desastres naturales: por dónde llegará la primera gran crisis del cambio climático",date:"2023-09-26T17:18:52.789Z",img:"https:\u002F\u002Fucarecdn.com\u002Fcc501a42-3814-43fd-b958-9f52ef28a489\u002F",autor:"Laure Delalande",medio:d,link:"https:\u002F\u002Fwww.animalpolitico.com\u002Fanalisis\u002Finvitades\u002Fescasez-agua-desastres-naturales-crisis-climatica",category:a,extracto:"Antes me preguntaba si la primera gran crisis iba a ser de escasez de agua, de desastres naturales repetidos y masivos, de baja drástica en las cosechas… Ahora me va quedando cada vez más claro que todo eso puede suceder de manera paralela, e incluso, reforzarse mutuamente.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fescasez_de_agua_o_desastres_naturales_por_donde_llegara_la_primera_gran_crisis_del_cambio_climatico",extension:c,createdAt:l,updatedAt:l},{slug:"los_retos_para_el_desarrollo_urbano_sostenible_en_la_era_de_la_opacidad_mexicana",title:"Los retos para el desarrollo urbano sostenible en la era de la opacidad mexicana",date:"2023-08-30T17:01:13.609Z",img:"https:\u002F\u002Fucarecdn.com\u002F61de1e82-23c0-499e-8a0d-f1980d4a6773\u002F","img-alt":"Ciudades sostenibles",autor:"Sebastián Guzmán y Yeshua Fierro",medio:f,link:"https:\u002F\u002Fobras.expansion.mx\u002Fopinion\u002F2023\u002F08\u002F30\u002Flos-retos-para-el-desarrollo-urbano-sostenible-en-la-era-de-la-opacidad-mexicana?_gl=1*z6y6wn*_ga*MjA0MzE4MjE3NC4xNjY3ODQwOTU2*_ga_0SB2V0KTR2*MTY5MzQxMjY3Mi4zMS4xLjE2OTM0MTQzODUuNTkuMC4w",category:a,extracto:"El desarrollo urbano a nivel nacional enfrenta diversos desafíos, y uno de los más significativos es la falta de información pública adecuada para respaldar un crecimiento sostenible y planificado.",toc:[],dir:b,path:"\u002Fcolumnas\u002Flos_retos_para_el_desarrollo_urbano_sostenible_en_la_era_de_la_opacidad_mexicana",extension:c,createdAt:m,updatedAt:m}],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("desarrollo-sostenible","\u002Fcolumnas",".md","Animal Político","Juan Felipe Santana","Expansión","2025-04-23T06:21:15.368Z","2024-10-02T22:32:44.076Z","2024-10-02T22:32:44.071Z","2024-10-02T22:32:44.073Z","2024-10-02T22:32:44.067Z","2023-10-09T22:42:25.550Z","2023-09-12T15:29:17.035Z")));